//! FFI wrappers for [`YieldedValues`] operations, called from C code.
//!
//! The corresponding C header is auto-generated by cheadergen at
//! `headers/yielded_values_ffi.h`.

use ffi::RLookupKey;
use index_result::{RSIndexResult, YieldedValues, YieldedValuesSlice};

/// Creates an empty [`YieldedValues`]. Does not allocate.
///
/// Use this to initialize the `yieldedValues` field when constructing an
/// `RSIndexResult` in place on the C side. Zero-initialization (e.g.
/// designated initializers, `memset`, `calloc`) produces an invalid
/// `YieldedValues` because the underlying `ThinVec` represents the empty
/// state with a non-null sentinel pointer to a static header — not
/// `NULL`.
#[unsafe(no_mangle)]
pub const extern "C" fn YieldedValues_New() -> YieldedValues<'static> {
    YieldedValues::new()
}

/// Moves all yielded values from `child` into `parent`, leaving `child` empty.
///
/// # Safety
///
/// 1. `parent` must point to a valid `YieldedValues` (e.g. `&result.yieldedValues`).
/// 2. `child` must point to a valid `YieldedValues`, or be null (no-op).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn YieldedValues_Concat<'a>(
    parent: *mut YieldedValues<'a>,
    child: *mut YieldedValues<'a>,
) {
    debug_assert!(!parent.is_null(), "parent must not be null");
    if child.is_null() {
        return;
    }
    // SAFETY: caller guarantees both pointers are valid.
    let child = unsafe { &mut *child };
    if child.is_empty() {
        return;
    }
    // SAFETY: caller guarantees `parent` is a valid, non-null pointer.
    let parent = unsafe { &mut *parent };
    parent.concat(child);
}

/// Appends a single yielded value to the result.
///
/// # Safety
///
/// 1. `r` must point to a valid `RSIndexResult` and cannot be null.
/// 2. `key` must be a valid `*const RLookupKey` that outlives the result
///    (or null).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn IndexResult_AddYieldedValue(
    r: *mut RSIndexResult,
    key: *const RLookupKey,
    val: f64,
) {
    debug_assert!(!r.is_null(), "result must not be null");

    // SAFETY: caller guarantees validity (1).
    let result = unsafe { &mut *r };
    let values = result.yielded_values_mut();
    if key.is_null() {
        values.push_without_key(val);
    } else {
        // SAFETY: `key` is non-null (checked above) and valid per caller guarantee (2).
        values.push_with_key(unsafe { &*key }, val);
    }
}

/// Clears all of the result's yielded values.
///
/// # Safety
///
/// 1. `r` must point to a valid `RSIndexResult` and cannot be null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn IndexResult_ResetYieldedValues(r: *mut RSIndexResult) {
    debug_assert!(!r.is_null(), "result must not be null");

    // SAFETY: caller guarantees validity (1).
    let result = unsafe { &mut *r };
    result.yielded_values.reset();
}

/// Resets aggregate-specific fields on an `RSIndexResult`: doc_id, freq,
/// field_mask, child records, and yielded values.
///
/// # Safety
///
/// 1. `r` must point to a valid `RSIndexResult` and cannot be null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn IndexResult_ResetAggregate(r: *mut RSIndexResult) {
    debug_assert!(!r.is_null(), "result must not be null");

    // SAFETY: caller guarantees validity (1).
    let result = unsafe { &mut *r };
    result.reset_aggregate();
}

/// Returns a read-only slice view of `values` for zero-copy
/// iteration from C.
///
/// # Safety
///
/// 1. `values` must point to a valid `YieldedValues` (e.g. `&result.yieldedValues`).
/// 2. The returned slice borrows from the `YieldedValues`; the caller must
///    not mutate or free the `YieldedValues` while the slice is in use.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn YieldedValues_AsSlice(values: *const YieldedValues) -> YieldedValuesSlice {
    debug_assert!(!values.is_null(), "values must not be null");

    // SAFETY: caller guarantees validity (1).
    let vec = unsafe { &*values };
    vec.as_c_slice()
}

/// Finds the first yielded value whose key matches `key` (pointer equality) and
/// replaces its value.
///
/// # Safety
///
/// 1. `values` must point to a valid `YieldedValues` (e.g. `&result.yieldedValues`).
/// 2. `key` must point to a valid `RLookupKey`. Compared by pointer identity.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn YieldedValues_UpdateValue(
    values: *mut YieldedValues,
    key: *const RLookupKey,
    new_value: f64,
) {
    debug_assert!(!values.is_null(), "values must not be null");
    debug_assert!(!key.is_null(), "key must not be null");

    // SAFETY: caller guarantees validity (1) and (2).
    let vec = unsafe { &mut *values };
    // SAFETY: caller guarantees `key` is valid and non-null (2); checked by debug_assert above.
    let key = unsafe { &*key };
    if let Some(entry) = vec.find_by_key_mut(key) {
        entry.set_value(new_value);
    }
}
